for entry in PATCH:
    path = Path(entry['path'])
    source = path.read_text()
    assert blob_sha(source) == entry['before'], 'Source changed; refusing a blind edit: ' + str(path)
    lines = source.splitlines(True)
    for start, end, content in reversed(entry['edits']):
        lines[start:end] = [content]
    result = ''.join(lines)
    assert blob_sha(result) == entry['after'], 'Unexpected output: ' + str(path)
    path.write_text(result)
